function currentFinancialYear(date=new Date()){const start=date.getMonth()>=3?date.getFullYear():date.getFullYear()-1;return `${start}–${String(start+1).slice(-2)}`}
function localISODate(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function financialYearFromStart(start:number){return `${start}–${String(start+1).slice(-2)}`}
function amcCollectionFinancialYear(date=new Date()){return date.getMonth()<3?financialYearFromStart(date.getFullYear()):currentFinancialYear(date)}
function isAmcAdvanceWindow(date=new Date()){return date.getMonth()<=2}
function financialYears(){const years=new Set([currentFinancialYear(),'2026–27','2027–28']);try{const entries=JSON.parse(localStorage.getItem('apclrwa_admin_ledger')||'[]');if(Array.isArray(entries))entries.forEach((entry:any)=>{if(typeof entry.financialYear==='string'&&/^\d{4}–\d{2}$/.test(entry.financialYear))years.add(entry.financialYear);if(typeof entry.amcForFinancialYear==='string'&&/^\d{4}–\d{2}$/.test(entry.amcForFinancialYear))years.add(entry.amcForFinancialYear)});const rates=JSON.parse(localStorage.getItem('apclrwa_amc_rates')||'[]');if(Array.isArray(rates))rates.forEach((rate:any)=>{if(typeof rate.financialYear==='string'&&/^\d{4}–\d{2}$/.test(rate.financialYear))years.add(rate.financialYear)})}catch{}return [...years].sort((a,b)=>Number(b.slice(0,4))-Number(a.slice(0,4)))}

